    KEY `idx_metadata_operations_tenant_resource` (`tenant_id`, `resource_id`),
    KEY `idx_metadata_operations_tenant_subject_created` (`tenant_id`, `originating_subject_id`, `created_at` DESC, `id` DESC)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
