CREATE TABLE IF NOT EXISTS `device_access_bindings` (
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `device_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `direct_access` JSON NULL,
    `device_parameters` JSON NOT NULL DEFAULT ('{}'),
    `configuration_generation` BIGINT NOT NULL DEFAULT 1,
    `pending_operation_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `runtime_provider_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `service_instance_id` VARCHAR(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `runtime_namespace` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `runtime_external_id` VARCHAR(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `template_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    CONSTRAINT `device_access_bindings_configuration_exclusive` CHECK (((template_id IS NULL) OR (direct_access IS NULL))),
    CONSTRAINT `device_access_bindings_direct_access_object` CHECK (((direct_access IS NULL) OR (JSON_TYPE(direct_access) = 'OBJECT'))),
    CONSTRAINT `device_access_bindings_generation_range` CHECK (((configuration_generation >= 1) AND (configuration_generation <= '9007199254740991'))),
    PRIMARY KEY (`tenant_id`, `device_id`),
    CONSTRAINT `device_access_bindings_runtime_external_id_nonempty` CHECK (((runtime_external_id IS NULL) OR (CHAR_LENGTH(TRIM((runtime_external_id))) > 0))),
    CONSTRAINT `device_access_bindings_runtime_identity_complete` CHECK ((((((runtime_provider_id IS NOT NULL) + (runtime_namespace IS NOT NULL) + (runtime_external_id IS NOT NULL)) = 0) AND (service_instance_id IS NULL)) OR (((runtime_provider_id IS NOT NULL) + (runtime_namespace IS NOT NULL) + (runtime_external_id IS NOT NULL)) = 3))),
    CONSTRAINT `device_access_bindings_runtime_namespace_nonempty` CHECK (((runtime_namespace IS NULL) OR (CHAR_LENGTH(TRIM((runtime_namespace))) > 0))),
    CONSTRAINT `device_access_bindings_runtime_provider_nonzero` CHECK (((runtime_provider_id IS NULL) OR (runtime_provider_id <> '00000000-0000-0000-0000-000000000000'))),
    CONSTRAINT `device_access_bindings_service_instance_nonempty` CHECK (((service_instance_id IS NULL) OR (CHAR_LENGTH(TRIM((service_instance_id))) > 0))),
    CONSTRAINT `device_access_bindings_unconfigured_parameters_empty` CHECK (((template_id IS NOT NULL) OR (direct_access IS NOT NULL) OR (device_parameters = CAST('{}' AS JSON)))),
    CONSTRAINT `device_access_bindings_updated_by_nonempty` CHECK ((CHAR_LENGTH(TRIM((updated_by))) > 0)),
    KEY `idx_device_access_bindings_pending_operation` (`tenant_id`, `pending_operation_id`),
    KEY `idx_device_access_bindings_runtime_instance` (`tenant_id`, `runtime_provider_id`, `service_instance_id`, `device_id`),
    KEY `idx_device_access_bindings_template` (`tenant_id`, `template_id`, `device_id`),
    `uq_device_access_bindings_runtime_instance_identity__uk` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF((((service_instance_id IS NOT NULL) AND (runtime_external_id IS NOT NULL))) AND `runtime_provider_id` IS NOT NULL AND `service_instance_id` IS NOT NULL AND `runtime_namespace` IS NOT NULL AND `runtime_external_id` IS NOT NULL, SHA2(CONCAT_WS(CHAR(31), `runtime_provider_id`, `service_instance_id`, `runtime_namespace`, `runtime_external_id`), 256), NULL)) STORED,
    UNIQUE KEY `uq_device_access_bindings_runtime_instance_identity` (`uq_device_access_bindings_runtime_instance_identity__uk`),
    `uq_device_access_bindings_runtime_no_instance_identity__uk` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF((((service_instance_id IS NULL) AND (runtime_external_id IS NOT NULL))) AND `runtime_provider_id` IS NOT NULL AND `runtime_namespace` IS NOT NULL AND `runtime_external_id` IS NOT NULL, SHA2(CONCAT_WS(CHAR(31), `runtime_provider_id`, `runtime_namespace`, `runtime_external_id`), 256), NULL)) STORED,
    UNIQUE KEY `uq_device_access_bindings_runtime_no_instance_identity` (`uq_device_access_bindings_runtime_no_instance_identity__uk`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
-- @@
CREATE TABLE IF NOT EXISTS `device_command_executions` (
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `device_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `identifier` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `snapshot_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `parameters` JSON NOT NULL,
    `label` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `delivery_mode` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'immediate',
    `timeout_seconds` INT NOT NULL DEFAULT 30,
    `expires_at` DATETIME(6) NULL,
    `state` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'pending',
    `reason` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `runtime_message_id` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `accepted_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `delivery_at` DATETIME(6) NULL,
    `acknowledged_at` DATETIME(6) NULL,
    `created_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `device_command_executions_created_by_nonempty` CHECK (((CHAR_LENGTH(TRIM((created_by))) >= 1) AND (CHAR_LENGTH(TRIM((created_by))) <= 128))),
    CONSTRAINT `device_command_executions_delivery_mode_valid` CHECK (((delivery_mode) IN ('immediate', 'when_online'))),
    CONSTRAINT `device_command_executions_identifier_nonempty` CHECK ((CHAR_LENGTH(identifier) >= 1)),
    CONSTRAINT `device_command_executions_message_id_nonempty` CHECK (((runtime_message_id IS NULL) OR (CHAR_LENGTH(TRIM((runtime_message_id))) > 0))),
    CONSTRAINT `device_command_executions_parameters_object` CHECK ((JSON_TYPE(parameters) = 'OBJECT')),
    PRIMARY KEY (`tenant_id`, `id`),
    CONSTRAINT `device_command_executions_state_valid` CHECK (((state) IN ('pending', 'accepted', 'delivered', 'acknowledged', 'failed', 'timed_out', 'expired', 'cancelled', 'unknown'))),
    CONSTRAINT `device_command_executions_timeout_range` CHECK (((timeout_seconds >= 1) AND (timeout_seconds <= 300))),
    KEY `idx_device_command_executions_device` (`tenant_id`, `device_id`, `accepted_at` DESC, `id` DESC),
    `uq_device_command_executions_message__uk` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(((runtime_message_id IS NOT NULL)) AND `tenant_id` IS NOT NULL AND `runtime_message_id` IS NOT NULL, SHA2(CONCAT_WS(CHAR(31), `tenant_id`, `runtime_message_id`), 256), NULL)) STORED,
    UNIQUE KEY `uq_device_command_executions_message` (`uq_device_command_executions_message__uk`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
-- @@
CREATE TABLE IF NOT EXISTS `device_credentials` (
    `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `device_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `template_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `credential_owner_kind` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (
CASE
    WHEN (device_id IS NULL) THEN 'template'
    ELSE 'device'
END) STORED,
    `credential_owner_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (COALESCE(device_id, template_id)) STORED,
    `purpose` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `kind` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `protection_mode` VARCHAR(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `status` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'pending',
    `public_identifier` VARCHAR(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `verifier` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `fingerprint_key_id` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `fingerprint` VARBINARY(255) NOT NULL,
    `ciphertext` LONGBLOB NULL,
    `key_id` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `cipher_suite` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `nonce` LONGBLOB NULL,
    `public_certificate` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `rotation_operation_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `supersedes_credential_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `created_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `resource_version` BIGINT NOT NULL DEFAULT 1,
    `activated_at` DATETIME(6) NULL,
    `revoked_at` DATETIME(6) NULL,
    `revoked_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `revocation_reason` VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `expires_at` DATETIME(6) NULL,
    CONSTRAINT `device_credentials_audit_actor_valid` CHECK ((((CHAR_LENGTH(TRIM((created_by))) >= 1) AND (CHAR_LENGTH(TRIM((created_by))) <= 128)) AND ((CHAR_LENGTH(TRIM((updated_by))) >= 1) AND (CHAR_LENGTH(TRIM((updated_by))) <= 128)))),
    CONSTRAINT `device_credentials_expiry_valid` CHECK (((expires_at IS NULL) OR ((expires_at > created_at) AND ((activated_at IS NULL) OR (expires_at > activated_at))))),
    CONSTRAINT `device_credentials_fingerprint_shape` CHECK (((LENGTH(fingerprint) = 32) AND ((((kind) = 'x509') AND ((protection_mode) = 'public_certificate') AND ((fingerprint_key_id IS NULL) OR ((CHAR_LENGTH((fingerprint_key_id)) >= 1) AND (CHAR_LENGTH((fingerprint_key_id)) <= 128)))) OR ((fingerprint_key_id IS NOT NULL) AND ((CHAR_LENGTH((fingerprint_key_id)) >= 1) AND (CHAR_LENGTH((fingerprint_key_id)) <= 128)))))),
    CONSTRAINT `device_credentials_kind_valid` CHECK (((kind) IN ('token', 'username_password', 'x509'))),
    CONSTRAINT `device_credentials_lifecycle_time_valid` CHECK ((((activated_at IS NULL) OR (activated_at >= created_at)) AND ((revoked_at IS NULL) OR (revoked_at >= created_at)))),
    UNIQUE KEY `device_credentials_owner_id_unique` (`tenant_id`, `credential_owner_kind`, `credential_owner_id`, `purpose`, `id`),
    CONSTRAINT `device_credentials_owner_purpose_valid` CHECK ((((device_id IS NOT NULL) AND (template_id IS NULL) AND ((purpose) = 'device_access')) OR ((device_id IS NULL) AND (template_id IS NOT NULL) AND ((purpose) = 'template_enrollment')))),
    PRIMARY KEY (`id`),
    CONSTRAINT `device_credentials_protection_shape_valid` CHECK (((((protection_mode) = 'verifier') AND (verifier IS NOT NULL) AND ((LENGTH(TRIM(verifier)) >= 1) AND (LENGTH(TRIM(verifier)) <= 8192)) AND (ciphertext IS NULL) AND (key_id IS NULL) AND (cipher_suite IS NULL) AND (nonce IS NULL) AND (public_certificate IS NULL)) OR (((protection_mode) = 'encrypted') AND (verifier IS NULL) AND (ciphertext IS NOT NULL) AND ((LENGTH(ciphertext) >= 17) AND (LENGTH(ciphertext) <= 8208)) AND (key_id IS NOT NULL) AND ((CHAR_LENGTH((key_id)) >= 1) AND (CHAR_LENGTH((key_id)) <= 128)) AND ((cipher_suite) = 'AES-256-GCM') AND (nonce IS NOT NULL) AND (LENGTH(nonce) = 12) AND (public_certificate IS NULL)) OR (((protection_mode) = 'public_certificate') AND ((kind) = 'x509') AND (verifier IS NULL) AND (ciphertext IS NULL) AND (key_id IS NULL) AND (cipher_suite IS NULL) AND (nonce IS NULL) AND (public_certificate IS NOT NULL) AND (CHAR_LENGTH(TRIM(public_certificate)) > 0) AND ((LENGTH(public_certificate) >= 1) AND (LENGTH(public_certificate) <= 32768)) AND (POSITION(('PRIVATE KEY') IN (upper(public_certificate))) = 0)))),
    CONSTRAINT `device_credentials_public_identifier_length` CHECK (((public_identifier IS NULL) OR ((CHAR_LENGTH((public_identifier)) >= 1) AND (CHAR_LENGTH((public_identifier)) <= 256)))),
    CONSTRAINT `device_credentials_resource_version_range` CHECK (((resource_version >= 1) AND (resource_version <= '9007199254740991'))),
    CONSTRAINT `device_credentials_rotation_pair_valid` CHECK (((rotation_operation_id IS NULL) = (supersedes_credential_id IS NULL))),
    CONSTRAINT `device_credentials_status_valid` CHECK (((((status) = 'pending') AND (activated_at IS NULL) AND (revoked_at IS NULL) AND (revoked_by IS NULL) AND (revocation_reason IS NULL)) OR (((status) = 'active') AND (activated_at IS NOT NULL) AND (revoked_at IS NULL) AND (revoked_by IS NULL) AND (revocation_reason IS NULL)) OR (((status) = 'revoked') AND (revoked_at IS NOT NULL) AND (revoked_by IS NOT NULL) AND ((CHAR_LENGTH(TRIM((revoked_by))) >= 1) AND (CHAR_LENGTH(TRIM((revoked_by))) <= 128)) AND (revocation_reason IS NOT NULL) AND ((CHAR_LENGTH(TRIM((revocation_reason))) >= 1) AND (CHAR_LENGTH(TRIM((revocation_reason))) <= 512)) AND ((activated_at IS NULL) OR (revoked_at >= activated_at))))),
    CONSTRAINT `device_credentials_supersedes_not_self` CHECK (((supersedes_credential_id IS NULL) OR (supersedes_credential_id <> id))),
    CONSTRAINT `device_credentials_template_kind_valid` CHECK ((((purpose) <> 'template_enrollment') OR ((kind) = 'token'))),
    CONSTRAINT `device_credentials_template_status_valid` CHECK ((((purpose) <> 'template_enrollment') OR ((status) IN ('active', 'revoked')))),
    UNIQUE KEY `device_credentials_tenant_id_unique` (`tenant_id`, `id`),
    CONSTRAINT `device_credentials_x509_public_only` CHECK (((((kind) = 'x509') AND ((protection_mode) = 'public_certificate')) OR (((kind) <> 'x509') AND ((protection_mode) <> 'public_certificate')))),
    KEY `idx_device_credentials_fingerprint_lookup` (`tenant_id`, `purpose`, `fingerprint_key_id`, `fingerprint`),
    KEY `idx_device_credentials_owner_purpose_status` (`tenant_id`, `credential_owner_id`, `purpose`, `status`, `id`),
    KEY `idx_device_credentials_public_identifier` (`tenant_id`, `purpose`, `public_identifier`),
    KEY `idx_device_credentials_supersedes` (`tenant_id`, `credential_owner_kind`, `credential_owner_id`, `purpose`, `supersedes_credential_id`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
-- @@
CREATE TABLE IF NOT EXISTS `device_groups` (
    `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `parent_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `name` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `description` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `sort_order` INT NOT NULL DEFAULT 0,
    `resource_version` BIGINT NOT NULL DEFAULT 1,
    `created_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `updated_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `deleted_at` DATETIME(6) NULL,
    CONSTRAINT `device_groups_name_check` CHECK ((CHAR_LENGTH(TRIM((name))) > 0)),
    PRIMARY KEY (`id`),
    CONSTRAINT `device_groups_resource_version_check` CHECK ((resource_version > 0)),
    CONSTRAINT `device_groups_sort_order_check` CHECK ((sort_order >= 0)),
    UNIQUE KEY `device_groups_tenant_id_id_key` (`tenant_id`, `id`),
    KEY `idx_device_groups_parent_order` (`tenant_id`, `parent_id`, `sort_order`, `id`),
    `uq_device_groups_root_name__uk` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF((((parent_id IS NULL) AND (deleted_at IS NULL))) AND `tenant_id` IS NOT NULL AND `name` IS NOT NULL, SHA2(CONCAT_WS(CHAR(31), `tenant_id`, `name`), 256), NULL)) STORED,
    UNIQUE KEY `uq_device_groups_root_name` (`uq_device_groups_root_name__uk`),
    `uq_device_groups_tenant_parent_name__uk` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF((((parent_id IS NOT NULL) AND (deleted_at IS NULL))) AND `tenant_id` IS NOT NULL AND `parent_id` IS NOT NULL AND `name` IS NOT NULL, SHA2(CONCAT_WS(CHAR(31), `tenant_id`, `parent_id`, `name`), 256), NULL)) STORED,
    UNIQUE KEY `uq_device_groups_tenant_parent_name` (`uq_device_groups_tenant_parent_name__uk`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
-- @@
CREATE TABLE IF NOT EXISTS `device_group_members` (
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `group_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `device_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `created_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
