CREATE TABLE IF NOT EXISTS `device_runtime_outbox` (
    `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `device_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `operation_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `kind` VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `generation` BIGINT NOT NULL,
    `desired` JSON NOT NULL,
    `state` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'pending',
    `attempts` INT NOT NULL DEFAULT 0,
    `last_error` LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `applied_at` DATETIME(6) NULL,
    `updated_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    CONSTRAINT `device_runtime_outbox_applied_pair` CHECK ((((state) = 'applied') = (applied_at IS NOT NULL))),
    CONSTRAINT `device_runtime_outbox_attempts_nonnegative` CHECK ((attempts >= 0)),
    CONSTRAINT `device_runtime_outbox_desired_object` CHECK ((JSON_TYPE(desired) = 'OBJECT')),
    CONSTRAINT `device_runtime_outbox_generation_range` CHECK (((generation >= 1) AND (generation <= '9007199254740991'))),
    CONSTRAINT `device_runtime_outbox_kind_valid` CHECK (((kind) IN ('administrative_state', 'template_binding', 'gateway_binding', 'device_deletion', 'credential_change', 'device_renumber'))),
    UNIQUE KEY `device_runtime_outbox_operation_unique` (`tenant_id`, `operation_id`),
    PRIMARY KEY (`id`),
    CONSTRAINT `device_runtime_outbox_state_valid` CHECK (((state) IN ('pending', 'applied', 'failed'))),
    CONSTRAINT `device_runtime_outbox_updated_by_nonempty` CHECK (((CHAR_LENGTH(TRIM((updated_by))) >= 1) AND (CHAR_LENGTH(TRIM((updated_by))) <= 128))),
    KEY `idx_device_runtime_outbox_pending` (`created_at`, `id`),
    KEY `idx_device_runtime_outbox_tenant_device` (`tenant_id`, `device_id`, `created_at` DESC)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
