    `state` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'ready',
    `expires_at` DATETIME(6) NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `created_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `closed_at` DATETIME(6) NULL,
    CONSTRAINT `device_simulation_sessions_closed_pair` CHECK ((((state) = 'closed') = (closed_at IS NOT NULL))),
    CONSTRAINT `device_simulation_sessions_created_by_nonempty` CHECK (((CHAR_LENGTH(TRIM((created_by))) >= 1) AND (CHAR_LENGTH(TRIM((created_by))) <= 128))),
    PRIMARY KEY (`id`),
    CONSTRAINT `device_simulation_sessions_state_valid` CHECK (((state) IN ('ready', 'closed'))),
    UNIQUE KEY `device_simulation_sessions_tenant_id_unique` (`tenant_id`, `id`),
    CONSTRAINT `device_simulation_sessions_version_range` CHECK (((profile_version >= 1) AND (profile_version <= '9007199254740991'))),
    KEY `idx_device_simulation_sessions_device` (`tenant_id`, `device_id`, `created_at` DESC)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
-- @@
CREATE TABLE IF NOT EXISTS `device_simulation_runs` (
    `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `device_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `session_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `state` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `sent` INT NOT NULL DEFAULT 0,
    `failed` INT NOT NULL DEFAULT 0,
    `error` JSON NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `created_by` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    CONSTRAINT `device_simulation_runs_counts_nonnegative` CHECK (((sent >= 0) AND (failed >= 0))),
    CONSTRAINT `device_simulation_runs_created_by_nonempty` CHECK (((CHAR_LENGTH(TRIM((created_by))) >= 1) AND (CHAR_LENGTH(TRIM((created_by))) <= 128))),
    CONSTRAINT `device_simulation_runs_error_object` CHECK (((error IS NULL) OR (JSON_TYPE(error) = 'OBJECT'))),
    PRIMARY KEY (`id`),
    CONSTRAINT `device_simulation_runs_state_valid` CHECK (((state) IN ('pending', 'running', 'succeeded', 'failed', 'cancelled'))),
    UNIQUE KEY `device_simulation_runs_tenant_id_unique` (`tenant_id`, `id`),
    KEY `idx_device_simulation_runs_device` (`tenant_id`, `device_id`, `created_at` DESC)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
-- @@
CREATE TABLE IF NOT EXISTS `device_simulator_profiles` (
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `device_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `resource_version` BIGINT NOT NULL DEFAULT 1,
