CREATE TABLE IF NOT EXISTS `metadata_idempotency` (
    `tenant_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    `subject_id` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `operation_name` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `canonical_path` VARCHAR(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `idempotency_key` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `request_hash` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `state` VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'in_progress',
    `http_status` SMALLINT NULL,
    `response` JSON NULL,
    `response_hash` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `replay_until` DATETIME(6) NOT NULL,
    `request_key_id` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `credential_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `response_key_id` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `response_cipher_suite` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    `response_nonce` LONGBLOB NULL,
    `response_ciphertext` LONGBLOB NULL,
    CONSTRAINT `metadata_idempotency_canonical_path_check` CHECK (((canonical_path) LIKE '/%')),
    CONSTRAINT `metadata_idempotency_idempotency_key_check` CHECK (((LENGTH((idempotency_key)) >= 8) AND (LENGTH((idempotency_key)) <= 128))),
    CONSTRAINT `metadata_idempotency_idempotency_key_check1` CHECK ((REGEXP_LIKE(idempotency_key, '^[A-Za-z0-9._:-]+$', 'c'))),
    CONSTRAINT `metadata_idempotency_operation_name_check` CHECK ((CHAR_LENGTH(TRIM((operation_name))) > 0)),
    `metadata_idempotency__pk` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (SHA2(CONCAT_WS(CHAR(31), `tenant_id`, `subject_id`, `operation_name`, `canonical_path`, `idempotency_key`), 256)) STORED NOT NULL,
    PRIMARY KEY (`metadata_idempotency__pk`),
    KEY `metadata_idempotency__pk_lookup` (`tenant_id`, `subject_id`(64), `operation_name`(64), `canonical_path`(64), `idempotency_key`(64)),
    CONSTRAINT `metadata_idempotency_request_hash_check` CHECK ((REGEXP_LIKE(request_hash, '^[a-f0-9]{64}$', 'c'))),
    CONSTRAINT `metadata_idempotency_response_hash_check` CHECK (((response_hash IS NULL) OR (REGEXP_LIKE(response_hash, '^[a-f0-9]{64}$', 'c')))),
    CONSTRAINT `metadata_idempotency_state_check` CHECK (((state) IN ('in_progress', 'completed', 'failed', 'expired'))),
    CONSTRAINT `metadata_idempotency_subject_id_check` CHECK ((CHAR_LENGTH(TRIM((subject_id))) > 0)),
    CONSTRAINT `metadata_receipt_secret_shape_valid` CHECK ((((request_key_id IS NULL) AND (credential_id IS NULL) AND (response_key_id IS NULL) AND (response_cipher_suite IS NULL) AND (response_nonce IS NULL) AND (response_ciphertext IS NULL)) OR ((request_key_id IS NOT NULL) AND ((CHAR_LENGTH((request_key_id)) >= 1) AND (CHAR_LENGTH((request_key_id)) <= 128)) AND (credential_id IS NOT NULL) AND (response IS NULL) AND (response_hash IS NULL) AND ((((state) = 'completed') AND (response_key_id IS NOT NULL) AND ((CHAR_LENGTH((response_key_id)) >= 1) AND (CHAR_LENGTH((response_key_id)) <= 128)) AND ((response_cipher_suite) = 'AES-256-GCM') AND (response_nonce IS NOT NULL) AND (LENGTH(response_nonce) = 12) AND (response_ciphertext IS NOT NULL) AND ((LENGTH(response_ciphertext) >= 17) AND (LENGTH(response_ciphertext) <= 262160))) OR (((state) = 'expired') AND (response_key_id IS NULL) AND (response_cipher_suite IS NULL) AND (response_nonce IS NULL) AND (response_ciphertext IS NULL)))))),
    CONSTRAINT `metadata_receipt_state_response_valid` CHECK (((((state) = 'in_progress') AND (http_status IS NULL) AND (response IS NULL) AND (response_ciphertext IS NULL)) OR (((state) = 'completed') AND ((http_status >= 200) AND (http_status <= 299)) AND (((response IS NOT NULL) AND (response_ciphertext IS NULL)) OR ((response IS NULL) AND (response_ciphertext IS NOT NULL)))) OR (((state) = 'failed') AND ((http_status >= 400) AND (http_status <= 599))) OR (((state) = 'expired') AND (http_status = 409) AND (response IS NULL) AND (response_ciphertext IS NULL)))),
    KEY `idx_metadata_idempotency_in_progress` (`updated_at`),
    KEY `idx_metadata_idempotency_replay_until` (`replay_until`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
