    `resource_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
    `expected_resource_version` BIGINT NULL,
    `target_generation` BIGINT NULL,
    `desired_document` JSON NULL,
    `checkpoint` JSON NOT NULL DEFAULT ('{}'),
    `owner_receipt` JSON NULL,
    `error` JSON NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
