    CONSTRAINT `metadata_operation_items_failed_requires_error` CHECK ((((state) <> 'failed') OR (error IS NOT NULL))),
    CONSTRAINT `metadata_operation_items_input_digest_valid` CHECK ((REGEXP_LIKE(input_digest, '^[0-9a-f]{64}$', 'c'))),
    CONSTRAINT `metadata_operation_items_key_nonempty` CHECK (((CHAR_LENGTH(TRIM((item_key))) >= 1) AND (CHAR_LENGTH(TRIM((item_key))) <= 128))),
    CONSTRAINT `metadata_operation_items_owner_receipt_object` CHECK (((owner_receipt IS NULL) OR (JSON_TYPE(owner_receipt) = 'OBJECT'))),
    PRIMARY KEY (`tenant_id`, `operation_id`, `item_key`),
    CONSTRAINT `metadata_operation_items_resource_version_range` CHECK (((expected_resource_version IS NULL) OR ((expected_resource_version >= 1) AND (expected_resource_version <= '9007199254740991')))),
    CONSTRAINT `metadata_operation_items_source_row_positive` CHECK (((source_row IS NULL) OR ((source_row >= 1) AND (source_row <= 2147483647)))),
    CONSTRAINT `metadata_operation_items_state_valid` CHECK (((state) IN ('pending', 'succeeded', 'failed', 'skipped'))),
    CONSTRAINT `metadata_operation_items_target_generation_range` CHECK (((target_generation IS NULL) OR ((target_generation >= 1) AND (target_generation <= '9007199254740991')))),
    KEY `idx_metadata_operation_items_tenant_operation_state_key` (`tenant_id`, `operation_id`, `state`, `item_key`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin
